        title = LocalizedText("""Novena a María Desatanudos""", """Mary Undoer of Knots Novena - Unfailing Novena Prayer""", """Novena a Nossa Senhora Desatadora dos Nós (oração infalível)"""),
        patron = LocalizedText("""Santo patrón de nudos, problemas difíciles""", """Patron saint of knots, difficult problems""", """Novena a Nossa Senhora Desatadora dos Nós (oração infalível)"""),
        category = LocalizedText("""Novenas""", """Novenas""", """Novenas"""),
        description = LocalizedText("""María Desatanudos es un título de la Virgen María donde ella desata los nudos de nuestras vidas. Reza la Novena Infalible a María Desatanudos.""", """Mary Undoer of Knots is a title of the Virgin Mary where she unties the knots in our lives. Pray the Unfailing Novena to Mary Undoer of Knots.""", """Santo padroeiro de os nós, os problemas difíceis"""),
